import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.7He2WLS4.js";const p=JSON.parse('{"title":"Keyboard Shortcuts","description":"Complete keyboard shortcut reference for NectoProxy.","frontmatter":{"title":"Keyboard Shortcuts","description":"Complete keyboard shortcut reference for NectoProxy."},"headers":[],"relativePath":"features/keyboard-shortcuts.md","filePath":"features/keyboard-shortcuts.md","lastUpdated":1772297611000}'),a={name:"features/keyboard-shortcuts.md"};function c(s,t,i,l,n,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>NectoProxy is designed to be efficient with keyboard-driven workflows. Keyboard shortcuts let you navigate the UI, control traffic capture, toggle panels, search, and access features without reaching for the mouse.</p><h2 id="viewing-shortcuts-in-the-ui" tabindex="-1">Viewing Shortcuts in the UI <a class="header-anchor" href="#viewing-shortcuts-in-the-ui" aria-label="Permalink to &quot;Viewing Shortcuts in the UI&quot;">​</a></h2><p>NectoProxy includes a built-in <strong>keyboard shortcuts help panel</strong> that displays all available shortcuts:</p><ul><li>Press <strong><code>?</code></strong> (question mark) to open the keyboard shortcuts help panel</li><li>The panel shows all shortcuts organized by category</li><li>Press <strong><code>?</code></strong> again or <strong><code>Escape</code></strong> to close the panel</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The keyboard shortcuts help panel always shows the most current shortcuts, including any that may have been added or changed in updates. If you forget a shortcut, press <code>?</code> for a quick reference.</p></div><h2 id="shortcut-reference" tabindex="-1">Shortcut Reference <a class="header-anchor" href="#shortcut-reference" aria-label="Permalink to &quot;Shortcut Reference&quot;">​</a></h2><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Navigate up/down in the traffic list</td></tr><tr><td><code>Enter</code></td><td>Open the detail panel for the selected entry</td></tr><tr><td><code>Escape</code></td><td>Close the current panel or dialog</td></tr><tr><td><code>Home</code></td><td>Jump to the first entry in the traffic list</td></tr><tr><td><code>End</code></td><td>Jump to the last entry in the traffic list</td></tr><tr><td><code>Tab</code></td><td>Cycle through detail panel tabs (Headers, Body, Timing, etc.)</td></tr><tr><td><code>Shift+Tab</code></td><td>Cycle through detail panel tabs in reverse</td></tr></tbody></table><h3 id="traffic-control" tabindex="-1">Traffic Control <a class="header-anchor" href="#traffic-control" aria-label="Permalink to &quot;Traffic Control&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+R</code> / <code>Cmd+R</code></td><td>Toggle recording (start/stop capturing traffic)</td></tr><tr><td><code>Ctrl+X</code> / <code>Cmd+X</code></td><td>Clear all traffic in the active session</td></tr><tr><td><code>Ctrl+P</code> / <code>Cmd+P</code></td><td>Pause/resume the traffic list auto-scroll</td></tr><tr><td><code>Space</code></td><td>Toggle recording (alternative)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>Ctrl+X</code> clears all traffic in the active session without confirmation. The data is permanently removed. Make sure you export important traffic before clearing.</p></div><h3 id="panel-toggles" tabindex="-1">Panel Toggles <a class="header-anchor" href="#panel-toggles" aria-label="Permalink to &quot;Panel Toggles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+1</code> / <code>Cmd+1</code></td><td>Toggle the Rules panel</td></tr><tr><td><code>Ctrl+2</code> / <code>Cmd+2</code></td><td>Toggle the Breakpoints panel</td></tr><tr><td><code>Ctrl+3</code> / <code>Cmd+3</code></td><td>Toggle the Sessions panel</td></tr><tr><td><code>Ctrl+,</code> / <code>Cmd+,</code></td><td>Open Settings</td></tr><tr><td><code>Ctrl+D</code> / <code>Cmd+D</code></td><td>Toggle the Dashboard panel</td></tr></tbody></table><h3 id="search-command-palette" tabindex="-1">Search &amp; Command Palette <a class="header-anchor" href="#search-command-palette" aria-label="Permalink to &quot;Search &amp; Command Palette&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+F</code> / <code>Cmd+F</code></td><td>Focus the filter bar</td></tr><tr><td><code>Ctrl+Shift+F</code> / <code>Cmd+Shift+F</code></td><td>Open global search (across all sessions)</td></tr><tr><td><code>Ctrl+K</code> / <code>Cmd+K</code></td><td>Open the command palette</td></tr><tr><td><code>Escape</code></td><td>Close search or command palette</td></tr></tbody></table><h3 id="selection-actions" tabindex="-1">Selection &amp; Actions <a class="header-anchor" href="#selection-actions" aria-label="Permalink to &quot;Selection &amp; Actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+A</code> / <code>Cmd+A</code></td><td>Select all entries in the traffic list</td></tr><tr><td><code>Ctrl+Click</code> / <code>Cmd+Click</code></td><td>Add entry to selection (multi-select)</td></tr><tr><td><code>Shift+Click</code></td><td>Select a range of entries</td></tr><tr><td><code>Ctrl+C</code> / <code>Cmd+C</code></td><td>Copy selected request URL to clipboard</td></tr><tr><td><code>Ctrl+Shift+C</code> / <code>Cmd+Shift+C</code></td><td>Copy selected request as cURL</td></tr><tr><td><code>Ctrl+E</code> / <code>Cmd+E</code></td><td>Export selected entries as HAR</td></tr><tr><td><code>Delete</code></td><td>Delete selected entries from the traffic list</td></tr></tbody></table><h3 id="request-actions" tabindex="-1">Request Actions <a class="header-anchor" href="#request-actions" aria-label="Permalink to &quot;Request Actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Enter</code> / <code>Cmd+Enter</code></td><td>Replay the selected request</td></tr><tr><td><code>Ctrl+G</code> / <code>Cmd+G</code></td><td>Open code generation for the selected request</td></tr><tr><td><code>Ctrl+Shift+D</code> / <code>Cmd+Shift+D</code></td><td>Compare two selected entries (when exactly 2 are selected)</td></tr></tbody></table><h3 id="breakpoint-actions" tabindex="-1">Breakpoint Actions <a class="header-anchor" href="#breakpoint-actions" aria-label="Permalink to &quot;Breakpoint Actions&quot;">​</a></h3><p>When a breakpoint has intercepted a request or response:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>F5</code></td><td>Resume the intercepted request/response</td></tr><tr><td><code>F8</code></td><td>Resume the intercepted request/response (alternative)</td></tr><tr><td><code>Shift+F5</code></td><td>Drop the intercepted request/response</td></tr><tr><td><code>Ctrl+Enter</code> / <code>Cmd+Enter</code></td><td>Resume with modifications</td></tr></tbody></table><h3 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+N</code> / <code>Cmd+N</code></td><td>Create a new session</td></tr><tr><td><code>Ctrl+W</code> / <code>Cmd+W</code></td><td>Close (delete) the current session</td></tr><tr><td><code>Ctrl+Shift+]</code> / <code>Cmd+Shift+]</code></td><td>Switch to the next session</td></tr><tr><td><code>Ctrl+Shift+[</code> / <code>Cmd+Shift+[</code></td><td>Switch to the previous session</td></tr></tbody></table><h3 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>?</code></td><td>Toggle keyboard shortcuts help panel</td></tr><tr><td><code>F1</code></td><td>Open documentation</td></tr></tbody></table><h2 id="platform-differences" tabindex="-1">Platform Differences <a class="header-anchor" href="#platform-differences" aria-label="Permalink to &quot;Platform Differences&quot;">​</a></h2><p>NectoProxy detects your operating system and displays the appropriate modifier keys:</p><table tabindex="0"><thead><tr><th>Windows / Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>Ctrl</code></td><td><code>Cmd</code></td></tr><tr><td><code>Alt</code></td><td><code>Option</code></td></tr><tr><td><code>Shift</code></td><td><code>Shift</code></td></tr><tr><td><code>Delete</code></td><td><code>Delete</code> or <code>Fn+Backspace</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>All shortcuts in this documentation show both the Windows/Linux and macOS versions separated by <code>/</code>. The NectoProxy UI automatically displays the correct key for your platform.</p></div><h2 id="quick-reference-card" tabindex="-1">Quick Reference Card <a class="header-anchor" href="#quick-reference-card" aria-label="Permalink to &quot;Quick Reference Card&quot;">​</a></h2><p>Here are the most frequently used shortcuts for everyday debugging:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+K</code> / <code>Cmd+K</code></td><td>Command palette -- access any feature quickly</td></tr><tr><td><code>Ctrl+F</code> / <code>Cmd+F</code></td><td>Focus filter bar</td></tr><tr><td><code>Ctrl+Shift+F</code> / <code>Cmd+Shift+F</code></td><td>Global search across all sessions</td></tr><tr><td><code>Ctrl+R</code> / <code>Cmd+R</code></td><td>Toggle traffic recording</td></tr><tr><td><code>Ctrl+X</code> / <code>Cmd+X</code></td><td>Clear traffic</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>Navigate traffic list</td></tr><tr><td><code>Enter</code></td><td>Open request details</td></tr><tr><td><code>Escape</code></td><td>Close panel/dialog</td></tr><tr><td><code>Ctrl+Shift+C</code> / <code>Cmd+Shift+C</code></td><td>Copy as cURL</td></tr><tr><td><code>Ctrl+Enter</code> / <code>Cmd+Enter</code></td><td>Replay request</td></tr><tr><td><code>?</code></td><td>Show all shortcuts</td></tr></tbody></table><details class="details custom-block"><summary>Customizing Shortcuts</summary><p>Currently, NectoProxy uses a fixed set of keyboard shortcuts. Custom key bindings are planned for a future release. If a shortcut conflicts with your operating system or another application, you can use the command palette (<code>Ctrl+K</code>) as an alternative way to access any feature.</p></details><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Keyboard shortcuts are active when focus is on the NectoProxy Web UI. If focus is on an input field (such as the filter bar or a rule editor), some shortcuts may be suppressed to avoid interference with text input. Press <code>Escape</code> to return focus to the main UI and restore shortcut functionality.</p></div>',37)])])}const f=e(a,[["render",c]]);export{p as __pageData,f as default};
